    if ($n < $total && mt_rand(1, 100) <= 30) { $ins->execute([$slug, $vid, $iph, gmdate('Y-m-d H:i:s', $ts + 1)]); $n++; $planted++; } }   // old double write: same cookie, same tool, 1 second later
