  ok((int)$pdo->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name IN ('leads','subscribers')")->fetchColumn() === 0, 'phase3_business.sql was NOT run: leads and subscribers were not created (only events was extracted)');
  echo 'fingerprint before: ' . json_encode($before) . "\n"; $after = $fp($pdo); ok($after === $before, 'historical click records are IDENTICAL after the migrations (count, max id, fingerprint): ' . json_encode($after));
  [$rc, $out] = $cli($db, $root . '/database/analytics_install/00_preflight_readonly.sql'); ok($rc === 0 && strpos($out, 'fingerprint') !== false, 'the read-only preflight script runs without error');
