  putenv('AIHUB_ANALYTICS_SALT=' . str_repeat('s', 40)); $days = ['2026-11-17', '2026-11-18', '2026-11-19', '2026-11-20']; $exp = []; $tsOf = fn($d, $h, $m) => strtotime("$d $h:$m:00 UTC");
  foreach ($days as $i => $d) { $exp[$d] = ['views' => 0, 'vis' => [], 'bots' => 0]; for ($v = 0; $v < 5 + $i; $v++) for ($k = 0; $k < 3; $k++) { $uaK = $v % 2 ? $ua['m'] : $ua['d']; $path = $k === 0 ? '/' : '/tool.php?id=' . ($k === 1 ? 'chatgpt' : 'claude'); $_SERVER = ['HTTP_USER_AGENT' => $uaK, 'REMOTE_ADDR' => "198.51.100." . (10 + $v), 'HTTP_HOST' => 'aihubpedia.com', 'SCRIPT_NAME' => $k === 0 ? '/index.php' : '/tool.php', 'HTTP_REFERER' => $v % 3 === 0 ? 'https://www.google.com/' : ''];
      $row = analytics_build_row($_SERVER, [], 200, $tsOf($d, 9, $k * 2 + $v), $path); analytics_insert($pdo, $row); $exp[$d]['views']++; $exp[$d]['vis'][$row['visitor_hash']] = 1; } $_SERVER = ['HTTP_USER_AGENT' => 'Googlebot/2.1', 'HTTP_HOST' => 'aihubpedia.com', 'SCRIPT_NAME' => '/index.php']; analytics_insert($pdo, analytics_build_row($_SERVER, [], 200, $tsOf($d, 10, 0), '/')); }
  foreach ($days as $d) { foreach ([['chatgpt', 'yes', 'sponsored'], ['chatgpt', 'no', 'organic'], ['claude', 'no', 'organic']] as $e) event_insert($pdo, ['name' => 'outbound_click', 'ref' => $e[0], 'prop1' => $e[1], 'prop2' => $e[2]], '', false, $tsOf($d, 11, 0)); event_insert($pdo, ['name' => 'outbound_click', 'ref' => 'chatgpt', 'prop1' => 'no', 'prop2' => 'link'], 'abcdef0123456789', false, $tsOf($d, 11, 5)); }   // the last one is an old browser-style event: must not be counted
  ok((int)$pdo->query('SELECT COUNT(*) FROM page_views')->fetchColumn() === 3 * (5 + 6 + 7 + 8) + 4 && (int)$pdo->query('SELECT COUNT(*) FROM events')->fetchColumn() === 16, 'collectors wrote the expected raw rows (page_views and events)');
  ok((int)$pdo->query("SELECT COUNT(*) FROM page_views WHERE visitor_hash <> '' AND day = '2026-11-20'")->fetchColumn() === 24, 'visitor hashes are present for human views and the 8 daily visitors x 3 pages');
  ok($pdo->query("SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'page_views' AND column_name IN ('user_agent','ip','ip_address')")->fetchColumn() == 0, 'page_views has no user agent or IP column');
