  $t = $pdo->query("SELECT day, views_human, views_bot, visitors FROM adm_traffic_daily ORDER BY day")->fetchAll(PDO::FETCH_ASSOC); $okT = true; foreach ($t as $row) { $d = $row['day']; $okT = $okT && (int)$row['views_human'] === $exp[$d]['views'] && (int)$row['visitors'] === count($exp[$d]['vis']) && (int)$row['views_bot'] === 1; } ok(count($t) === 4 && $okT, 'rollup daily totals equal the hand-counted raw rows (views, visitors, bots separated)');
