  $cat = ['chatgpt' => ['name' => 'ChatGPT', 'category' => 'Chatbots'], 'claude' => ['name' => 'Claude', 'category' => 'Chatbots']]; $NOW = strtotime('2026-11-20 12:00:00 UTC');
  foreach (array_keys(anz_views()) as $v) { if ($v === 'details') continue; $h = anz_body($store, ['view' => $v, 'range' => '30d'], $cat, $NOW); ok(strpos($h, '<h1>Analytics</h1>') !== false && strpos($h, 'Fatal error') === false && strpos($h, 'Warning:') === false, "dashboard view $v renders against the real tables"); }
  foreach (array_keys(anz_export_names()) as $k) { $x = anz_export($store, $k, ['from' => '2026-11-01', 'to' => '2026-11-20'], [], $cat, '2026-11-20'); ok($x !== null || $k === 'placements_all', "export $k runs"); }
