  $GLOBALS['dbg'] = 1; $dupSql = (int)$pdo->query("SELECT COUNT(*) FROM (SELECT TIMESTAMPDIFF(SECOND, LAG(created_at) OVER (PARTITION BY visitor_id, tool_slug ORDER BY created_at, id), created_at) gap FROM tool_clicks WHERE visitor_id <> '') t WHERE gap <= 10")->fetchColumn(); echo "legacy: records={$L['records']} dups={$L['probable_duplicates']} (sql $dupSql) planted=$planted net={$L['net']} first={$L['first_day']} last={$L['last_day']}\n"; ok($L['probable_duplicates'] === $dupSql && $dupSql >= $planted * 0.95 && $dupSql <= $planted + 5, "probable duplicates ($dupSql) match the planted double writes ($planted)");
  ok($L['first_day'] === '2026-03-16' || $L['first_day'] === '2026-03-17', 'legacy history starts in March 2026'); $lh = anz_body($store, ['view' => 'legacy', 'range' => 'all'], $cat, $NOW); ok(strpos($lh, 'no page views and no visitors') !== false || strpos(strip_tags($lh), 'no page views and no visitors') !== false, 'legacy view states that these rows are not visitors or page views');
