  adma_rollup_range($pdo, '2026-11-20', '2026-11-20'); $dv = $store->dim('device', '2026-11-20', '2026-11-20', 10); ok(count($dv) === 2 && $store->status()['device_col'] === true, 'device dimension is rolled up and the dashboard sees the column');
